window.TEXTP = window.TEXTP || {};
window.TEXTP["76.15"] = [[["p","<b>Шейх аль-Альбани, да помилует его Аллах, упомянул это в книге «Мухтасар Сахих аль-Бухари», 1/295, 316, № 527. </b>"],["sep",""],["h2","ВОПРОС № 11: МОЛИТВА АР-РАГАИБ"],["h3","<b>Сказал наш шейх аль-Альбани, да помилует его Всевышний Аллах, в «ас-Сахиха», 2/737: </b>"],["p","«Сказал имам ан-Науауи в «Шарх Муслим»:"],["p","<i>«Ученые аргументировали этим хадисом</i><sup class=\"fn\">441</sup><i> о том, что нежелательно совершать эту молитву, являющуюся новшеством и именуемую «рагаиб». Пусть Аллах погубит того, кто придумал её! Поистине, она — порицаемое новшество». </i>"],["n",[[441,"Речь идёт о хадисе, в котором сказано: <b><i>«Не выделяйте ночь на пятницу совершением молитвы…». </i></b>"]]],["p","Эти слова от него передали и согласились с ним ас-Сан′ани, аш-Шаукани и другие ученые»."],["sep",""],["h2","ВОПРОС № 12: СОВЕРШЕНИЕ МОЛИТВЫ В ДВА РАКААТА ПОСЛЕ ПОСЕЩЕНИЯ БАНИ"],["h3","<b>Сказал автор книги «Та′алим аль-ислям», стр. 36, говоря о нормах совершения полного омовения: </b>"],["p","«Также следует совершить молитву в два ракаата после выхода из бани»."],["h3","<b>Сказал шейх аль-Альбани, да помилует его Всевышний Аллах, в «ад-Да′ифа», 1/606:</b>"],["p","«У этого нет никакой основы в книгах Сунны. Об этом не говорится даже в тех книгах, где приведены выдуманные хадисы. И я не знаю, чтобы хоть кто-то из имамов сказал подобное»."],["sep",""],["h2","ВОПРОС № 13: СОВЕРШЕНИЕ МОЛИТВЫ В ДВА РАКААТА ПУТНИКОМ"],["h3","<b>Сказал наш шейх аль-Альбани, да помилует его Всевышний Аллах, в «ад-Да′ифа», 1/551:</b>"],["p","«Затем ан-Науауи (да помилует его Аллах) аргументировал этим хадисом<sup class=\"fn\">442</sup> в пользу того, что путнику желательно совершить молитву в два ракаата перед выходом в путь. Это очевидно является ошибкой, ибо желательность — это религиозное постановление, и нельзя аргументировать в пользу желательности слабым хадисом. Посредством слабого хадиса не могут быть установлены религиозные постановления, как это известно. Эта молитва не передана от пророка (да благословит его Аллах и приветствует) и не является узаконенной. И это в отличие от молитвы после возвращения из пути. Эта молитва уже является сунной»."],["n",[[442,"Речь идёт о хадисе, в котором сказано: <b><i>«Раб (Аллаха) не оставлял своей семье ничего лучшего, чем два ракаата, которые он совершает у них тогда, когда желает отправиться в путь». </i></b>"]]],["sep",""],["h2","ВОПРОС № 14: СОВЕРШЕНИЕ МОЛИТВЫ ПОСЛЕ ОБЯЗАТЕЛЬНОЙ УТРЕННЕЙ МОЛИТВЫ (ФАДЖР)"],["h3","<b>Сказал наш шейх в «аль-Ируа», 2/236, после хадиса № 478</b><sup class=\"fn\">443</sup><b>:</b>"],["n",[[443,"В этом хадисе сказано: <b><i>«Когда выходит заря, нет молитвы, кроме двух ракаатов утренней молитвы (фаджр)». </i></b>"]]],["p","«<b>Польза</b>: передал аль-Бейхакы с достоверной цепочкой от Са′ида ибн уль-Мусеййяба, что однажды он увидел, как некий человек совершает после появления зари больше двух ракаатов и удлиняет поясные и земные поклоны, и запретил ему поступать так. Тот человек сказал: <i>«О Абу Мухаммад! Неужели Аллах накажет меня за молитву?!».</i> Са′ид ответил: <i>«Нет, но Он накажет тебя за противоречие Сунне». </i>"]],[["p","И это — один из прекрасных ответов Са′ида ибн уль-Мусеййяба, да помилует его Всевышний Аллах. Это — сильное орудие против сторонников новшеств, которые считают прекрасными разные новшества, аргументируя тем, что они просто поминают Аллаха и совершают молитву. Затем они порицают приверженцев Сунны за то, что те порицают их за совершение этих новшеств. Они обвиняют приверженцев Сунны в том, что те будто бы порицают их за поминание Аллаха и совершение молитвы. Но, на самом деле, приверженцы Сунны порицают их за то, что те противоречат Сунне, когда поминают Аллаха, совершают молитву и т. п.»."],["sep",""],["h2","ВОПРОС № 15: СОВЕРШЕНИЕ МОЛИТВЫ В КАКОМ-ЛИБО ОСОБОМ ВИДЕ, КОТОРЫЙ НЕ БЫЛ ПЕРЕДАН В КОРАНЕ И В СУННЕ"],["h3","<b>Сказал Ибн ус-Салях, да помилует его Всевышний Аллах, в «аль-Мусаджаля», стр. 18: </b>"],["p","«Сколько было молитв, принятых Аллахом, но при этом они совершались в каком-либо особом виде, который не был передан в Коране и в Сунне. Затем не говорят, что такие молитвы являются новшеством. А если даже кто-то и назовет это новшеством, то он скажет, что это новшество является благим, ибо у него есть основа в Коране или в Сунне»."],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, опровергая эти слова Ибн ус-Саляха в примечаниях к книге «аль-Мусаджаля», стр. 18:</b>"],["p","«Наоборот, это новшество, которое является заблуждением, ибо это — новшество в поклонении. А все новшества в поклонении являются заблуждением»."],["sep",""],["p","<b>А в примечаниях к посланию «ас-Сырат аль-мустакым», стр. 7, шейх высказался о хадисах, пришедших по поводу молитвы в срединную ночь месяца ша′бан. Он сказал о том, что все эти хадисы являются ложными и выдуманными. Затем он упомянул один достоверный хадис по поводу этой ночи</b><sup class=\"fn\">444</sup> <b>и сказал: </b>"],["n",[[444,"В этом хадисе сказано: <b><i>«В срединную ночь ша′бана Аллах смотрит на все Свои творения и прощает всем им (их грехи), кроме многобожника и враждующего (с мусульманами)».</i></b>"]]],["p","«Из того, что говорится о достоинстве этой ночи, не следует, что нужно выделять её особой молитвой, совершаемой в особом виде, с которым не пришёл мудрый шариат. Напротив, всё это является новшеством, которого мы обязаны сторониться. Мы обязаны держаться за то, на чём были сподвижники и праведные предшественники (да будет доволен ими Аллах). И да помилует Аллах того, кто сказал:"],["c","<i>«Всё благо заключено в следовании за предшественниками,</i>"],["c","<i>А всё зло — в новшествах тех, кто жил позже». </i>"],["sep",""],["p","ВОПРОС № 16: СОВЕРШЕНИЕ МОЛИТВЫ В ПЯТНАДЦАТЬ РАКААТОВ И ЧТЕНИЕ В КАЖДОМ РАКААТЕ АЯТОВ ИЗ ПЯТНАДЦАТИ СУР, И ПРОИЗНЕСЕНИЕ В КАЖДОМ РАКААТЕ ОСОБОЙ МОЛЬБЫ"],["h3","<b>Сказал Ибн ус-Салях, да помилует его Всевышний Аллах, в «аль-Мусаджаля», стр. 18: </b>"]],[["p","«Например, если человек ночью совершит молитву в пятнадцать ракаатов и прочитает в каждом ракаате аяты из пятнадцати сур, и выделит каждый ракаат какой-либо особой мольбой, то эта молитва будет принятой, а не отвергнутой. Никто не имеет права сказать, что это молитва является отвергнутой и является новшеством из-за того, что такой вид молитвы не был передан в Коране или в Сунне»."],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, опровергая эти слова Ибн ус-Саляха в примечаниях к книге «аль-Мусаджаля», стр. 18:</b>"],["p","«Напротив, эта молитва будет отвергнутой и будет новшеством. Никто не имеет права намеренно совершать такую молитву, ибо у такого вида молитвы нет основы. А заявления о том, что у этой молитвы есть основа, не принесут пользы, ибо мы не говорим об узаконенности самой молитвы, а говорим именно об узаконенности молитвы в таком виде. Нет сомнений в том, что такая молитва является новшеством, а, значит, она является заблуждением, ибо есть общие тексты, порицающие все новшества. И именно такую молитву имам аш-Шатыби в книге «аль-И′тисам» называет «бид′а идафия». «Бид′а идафия» — это один из видов новшеств. А другой вид новшеств — это «бид′а хакыкия», которое еще хуже, чем первое»<sup class=\"fn\">445</sup>."],["n",[[445,"Подробнее в главе № 4 первого раздела этой книги."]]],["sep",""],["h2","ВОПРОС № 17: СОВЕРШЕНИЕ МОЛИТВЫ В ДВА РАКААТА ПОСЛЕ КАЖДОЙ ПРОЙДЕННОЙ МИЛИ В ПУТИ"],["h3","<b>Сказал Абу Ну′айм в биографии аскета Абу-ль ′Аббаса аш-Ша′рани Ахмада ибн Мухаммада ибн Джа′фара:</b>"],["p","«Он был одним из праведников, стремящихся к совершению хаджа. И он совершал молитву в два ракаата после каждой пройденной мили»."],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ас-Сахиха», 5/436:</b>"],["p","«Я скажу: такая молитва является новшеством, которое не совершали предшественники. А их предводителем был господин всех пророков (мир ему и благословение Аллаха). Лучший путь — это путь Мухаммада!»."],["sep",""],["p","ВОПРОС № 18: СОВЕРШЕНИЕ МОЛИТВЫ ПОСЛЕ РИТУАЛЬНОГО ОБХОДА МЕЖДУ АС-САФА И АЛЬ-МАРВА (ВО ВРЕМЯ ПАЛОМНИЧЕСТВА) ПО АНАЛОГИИ С ОБХОДОМ ВОКРУГ КААБЫ"],["p","<b>Шейх аль-Альбани, да помилует его Аллах, упомянул этот вопрос в книгах «Салят ат-таравих», стр. 45; «Хадж пророка, да благословит его Аллах и приветствует», «аль-Манасик», «ас-Сильсиля ад-да′ифа», 2/328, № 928. </b>"],["sep",""],["h2","ВОПРОС № 19: СОВЕРШЕНИЕ ОСОБОЙ МОЛИТВЫ В ПЕРВУЮ ПЯТНИЦУ МЕСЯЦА РАДЖАБ"],["p","<b>Шейх аль-Альбани, да помилует его Аллах, упомянул этот вопрос в книге «Салят ат-таравих», стр. 44.</b>"],["sep",""],["h2","ВОПРОС № 20: СОВЕРШЕНИЕ МОЛИТВЫ В ДВЕНАДЦАТЬ РАКААТОВ, ОПИРАЯСЬ НА СЛАБЫЙ ХАДИС<sup class=\"fn\">446</sup> И ОПЫТ ЛЮДЕЙ"],["n",[[446,"Шейх, да помилует его Аллах, имеет в виду хадис, в котором сказано: <b><i>«Соверши ночью или днём двенадцать ракаатов, произнося ташаххуд после каждых двух ракаатов, а когда ты произнесешь ташаххуд в конце молитвы, то восхвали Всемогущего и Великого Аллаха, попроси благословения для пророка, а (также) прочитай в земном поклоне суру \"аль-Фатиха\" семь раз…», </i></b>и так далее до конца хадиса. Хадис является выдуманным (мавду′)."]]]],[["p","<b>Сказал наш шейх, да помилует его Аллах, в «Да′иф ат-Таргыб уа ттархиб», 1/216-217, после хадиса № 418: </b>"],["p","«Аль-Хаким сказал: <i>«Ахмад ибн Харб сказал: \"Я испробовал эту молитву и понял, что этот хадис — истина\". Сказал Ибрахим ибн ′Али ад-Дабили: \"Я испробовал эту молитву и понял, что этот хадис — истина\". И сказал нам Абу Закария: \"Я испробовал эту молитву и понял, что этот хадис — истина\". И я тоже испробовал эту молитву и понял, что этот хадис — истина».</i>"],["p","Я<sup class=\"fn\">447</sup> скажу: напротив, нельзя опираться в таких делах на опыт людей. И прекрасно сказал аш-Шаукани в «Тухфат аз-закирин», стр. 140, после того, как упомянул эти слова аль-Хакима:"],["n",[[447,"То есть аль-Альбани."]]],["p","<i>«Я скажу: Сунна не устанавливается через людской опыт. И если человек совершает что-то, думая, что это — Сунна, он не перестает быть совершающим новшество. Принятие мольбы (ду′а) не указывает на то, что причина принятия этой мольбы достоверно установлена от посланника Аллаха (да благословит его Аллах и приветствует)</i><sup class=\"fn\">448</sup><i>. Иногда Аллах принимает мольбу, даже если она не соответствует Сунне, ведь Он — Милостивейший из милостивых. А иногда принятие мольбы бывает завлечением (истидрадж). К тому же в этом так называемом «хадисе» есть противоречие пречистой Сунне. Ведь в Сунне твердо установлен запрет на чтение Корана в поясных и земных поклонах. И это — один из самых главных доводов, указывающих на то, что этот «хадис» является выдуманным. К тому же среди его передатчиков ′Умар ибн Харун ибн Язид ас-Сакафи аль-Бальхи, который относился к числу оставленных и обвиненных во лжи передатчиков, хоть он и был хафизом. Его хвалил Ибн Махди, но, вероятно, он хвалил его по причине его памяти. Также его ученик ′Амир ибн Хидаш. Вероятно, этот хадис относится к числу тех отвергаемых хадисов, которые он передавал. И удивительно, как такие ученые, как аль-Хаким, аль-Бейхакы, аль-Уахиди и те, кто после них, опирались на людской опыт в том, относительно чего все они знали, что это противоречит пречистой Сунне и ввергает человека в запретное». </i>"],["n",[[448,"Дело в том, что в конце этого хадиса сказано: <b><i>«…а затем проси (Аллаха) о своих нуждах, а затем подними голову и произнеси слова приветствия (саляма) направо и налево. И не обучай этой молитве глупцов, ибо они станут взывать к Аллаху посредством неё и получать ответ». </i></b>"]]],["sep",""],["p","ВОПРОС № 21: ИМЕНОВАНИЕ МОЛИТВЫ В ШЕСТЬ РАКААТОВ ПОСЛЕ ОБЯЗАТЕЛЬНОЙ ВЕЧЕРНЕЙ МОЛИТВЫ (МАГРИБ) МОЛИТВОЙ КАЮЩИХСЯ (САЛЯТ АЛЬ-АУУАБИН)"],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в примечаниях к книге «Мухтасар Сахих Муслим», хадис № 368: </b>"]],[["p","«В этом хадисе<sup class=\"fn\">449</sup> указание на то, что молитва «ад-духа» — это и есть та молитва, которую шариат называет молитвой кающихся (салят аль-аууабин). Что же касается именования таким термином молитвы, совершаемой после вечерней молитвы (магриб), то, насколько я знаю, этому нет основы в достоверной Сунне»."],["n",[[449,"Речь идёт о хадисе, в котором сказано: <b><i>«Время молитвы кающихся наступает тогда, когда земля начинает обжигать лапы верблюжат». </i></b>Передал Муслим."]]],["sep",""],["h3","<b>Также наш шейх, да помилует его Аллах, сказал в «Сахих ат-Таргыб», 1/423</b><sup class=\"fn\">450</sup><b>:</b>"],["n",[[450,"Шейх разъясняет хадис, в котором сказано: <b><i>«Молитву ад-духа не оберегает никто, кроме кающихся. Эта (молитва) — молитва кающихся».</i></b>"]]],["p","«Я скажу: в этом хадисе опровержение тем, которые называют шесть ракаатов, совершаемых после обязательной вечерней молитвы (магриб), молитвой кающихся (салят аль-аууабин). У этого нет основы, и даже сама эта молитва в шесть ракаатов не является установленной»."],["sep",""],["h3","<b>Также он сказал в «ас-Сильсиля ад-да′ифа», 1/680, после хадиса № 467</b><sup class=\"fn\">451</sup><b>:</b>"],["n",[[451,"В этом хадисе сказано: <b><i>«Тому, кто совершит между вечерней (магриб) и ночной (′иша) молитвами (добровольную молитву) в двадцать ракаатов, Аллах возведёт дом в Раю». </i></b>И после него также приведен следующий хадис: <b><i>«Если кто-либо совершит шесть ракаатов после вечерней (магриб) молитвы…». </i></b>Оба этих хадиса являются очень слабыми."]]],["p","«Знай, что все хадисы, которые побуждают совершать определенное количество ракаатов между вечерней (магриб) и ночной (′иша) молитвами, не являются достоверными. Некоторые из них более слабые, чем другие. Достоверно установлено, что пророк (да благословит его Аллах и приветствует) совершал молитву в это время, но не установлено достоверно определенное количество ракаатов. Что же касается слов пророка (да благословит его Аллах и приветствует) на этот счёт, то всё, что передано от него на эту тему, является слабым, поэтому нельзя совершать деяния в соответствии с этими хадисами»."],["sep",""],["h2","ВОПРОС № 22: СОВЕРШЕНИЕ МОЛИТВЫ В ДВА РАКААТА ПОСЛЕ ВСТУПЛЕНИЯ В ИХРАМ В МИКАТЕ"],["p","′Умар ибн уль-Хаттаб (да будет доволен им Аллах) слышал, как посланник Аллаха (да благословит его Аллах и приветствует) говорил: <b><i>«Я находился в ‘Акыке</i></b><sup class=\"fn\">452</sup><b><i> и ночью ко мне явился вестник от моего Господа (с повелением) совершить молитву в этой благодатной долине».</i></b>"],["n",[[452,"‘Акык — долина, располагающаяся в четырех милях от Медины."]]],["h3","<b>Сказал наш шейх, да помилует его Аллах, в «Сахих Сунан Аби Дауд», 6/58:</b>"],["p","«В этом хадисе указание на достоинство совершения молитвы в Зуль-Хулейфе<sup class=\"fn\">453</sup>. Этот хадис является общим и не указывает конкретно на обязательную или желательную молитву. В нём нет довода на те два ракаата, которые совершают паломники перед вступлением в ихрам, ибо насчёт этих двух ракаатов нет ничего достоверного от пророка (да благословит его Аллах и приветствует). Если человек совершит любую обязательную или желательную молитву (в Зуль-Хулейфе), он обретет это достоинство, если пожелает Всевышний Аллах»."],["n",[[453,"Место, где вступают в ихрам жители Медины и те, кто отправляются в паломничество с их стороны."]]],["sep",""],["h3","<b>Также шейх сказал в книге «Обряды хаджа и ′умры», стр. 14:</b>"]],[["p","«Нет какой-то особенной молитвы, совершаемой при вступлении в ихрам, но если человек должен совершить какую-либо молитву в это время, он совершает её, а затем вступает в ихрам, следуя примеру посланника Аллаха (да благословит его Аллах и приветствует), который повелел людям вступить в ихрам после обеденной молитвы (зухр). Однако, если человек вступает в ихрам в Зуль-Хулейфе, то ему желательно совершить молитву в этом месте, но это делается не по причине вступления в ихрам, а по причине благодати этого места»."],["sep",""],["h2","ГЛАВА № 6 — НОВШЕСТВА, СВЯЗАННЫЕ С МОЛИТВАМИ, СОВЕРШАЕМЫМИ В ПУТИ"],["h2","ВОПРОС № 1: СОВЕРШЕНИЕ ПОЛНЫХ МОЛИТВ В ПУТИ<sup class=\"fn\">454</sup>"],["n",[[454,"Речь идёт о том, кто намеренно отказывается сокращать молитвы в пути."]]],["p","<b>Шейх аль-Альбани, да помилует его Аллах, упомянул этот вопрос в книге «Салят ат-таравих», стр. 37.</b>"],["sep",""],["h2","ГЛАВА № 7 — ИСКУПЛЕНИЕ ПРОПУЩЕННЫХ МОЛИТВ"],["h3","<b>Сказал аль-Касими, да помилует его Аллах, в «Ислях аль-масаджид», стр. 175-176:</b>"],["p","«Я помню, как однажды один из последователей предшественников спросил меня о том, что совершали некоторые знатоки фикха, пытаясь искупить пропущенные когда-то молитвы. Они говорили, что в знак искупления следует отдать мешочек дирхемов бедняку. Передано ли подобное от предшественников?! И если подобное не передано, то не лучше ли отказаться от этого, чтобы защитить себя от религиозных новшеств?! Я ответил, что нет сомнений в том, что это не передано от предшественников, но некоторые имамы разрешили поступать так, проведя аналогию с искуплением пропущенного поста, а также нарушенных клятв и обетов, ибо это приносит пользу беднякам и является милостыней, к которой побуждает наша религия. Именно поэтому в этом нет ничего греховного»."],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, комментируя эти слова: </b>"],["p","«Таково мнение автора (да помилует его Всевышний Аллах), но мы не считаем это мнение правильным, ибо оно не передано от предшественников, а всё благо заключено в следовании за ними. Лучше всего оставить подобное, как и сказал этот последователь предшественников. Более того мы обязаны отказаться от этого действия, ведь если человек ищет близости к Аллаху посредством того, что Он не узаконил, то это является величайшим заблуждением. А если человек называет это благим делом только лишь на основе того, что это приносит пользу бедняку, то это одна из наиболее странных аргументаций, которые только можно увидеть от последователей предшественников, среди которых и автор этой книги. Пусть Аллах простит нас и его! Ведь от таких ученых, как он, не скрыто, что цель не оправдывает средства. Мне кажется, что автор, да помилует его Всевышний Аллах, допустил эту ошибку по причине своего милостивого отношения к беднякам. В любом случае он получит награду, а Аллах — Тот, к Кому обращаются за помощью!»."],["h3","<b>Также на стр. 249-250 шейх аль-Альбани сказал: </b>"]],[["p","«Необходимо делать добро беднякам через те пути, которые узаконил Всевышний Аллах, а не через такие пути, которые не были известны предшественникам. Всё благо заключено в следовании за ними. И удивительно, что автор книги (да помилует его Всевышний Аллах) считает благими подобные новшества. И люди, которые совершали новшества, совершали их именно из-за таких сравнений и аналогий»."],["h2","РАЗДЕЛ ТРИНАДЦАТЫЙ — НОВШЕСТВА, СВЯЗАННЫЕ С МЕЧЕТЯМИ"],["h2","ГЛАВА № 1 — СОБРАНИЕ В МЕЧЕТИ БЕДНЯКОВ ДЛЯ ПРИНЯТИЯ МИЛОСТЫНИ ОТ ТЕХ, КТО ХОЧЕТ ИСКУПИТЬ ПРОПУЩЕННЫЕ МОЛИТВЫ"],["p","<b>Шейх аль-Альбани, да помилует его Аллах, упомянул это в книге «Ислях аль-масаджид», стр. 248-250. </b>"],["sep",""],["c","ГЛАВА № 2 — ЛЕЖАНИЕ В МЕЧЕТИ МЕЖДУ ДОПОЛНИТЕЛЬНОЙ МОЛИТВОЙ, СОВЕРШАЕМОЙ ПЕРЕД УТРЕННЕЙ МОЛИТВОЙ, И САМОЙ УТРЕННЕЙ МОЛИТВОЙ (ФАДЖР)"],["p","В хадисе со слов ′Аиши (да будет доволен ею Аллах) сказано: <i>«Затем он лёг на правый бок, пока не пришёл муаззин». </i>"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «Салят ат-таравих», стр. 90:</b>"],["p","«В этом ясное указание на то, что разрешено лежать между дополнительной молитвой, совершаемой перед утренней молитвой, и самой утренней молитвой, но мы не знаем, чтобы кто-нибудь из сподвижников делал это в мечети. Напротив, некоторые из них отвергли это. Необходимо делать это дома, ибо это соответствует сунне пророка (да благословит его Аллах и приветствует)»."],["sep",""],["h2","ГЛАВА № 3 — СОВЕРШЕНИЕ И′ТИКАФА<sup class=\"fn\">455</sup> В МОЛИТВЕННЫХ КОМНАТАХ, НАХОДЯЩИХСЯ В ДОМАХ"],["n",[[455,"И’тикаф — это постоянное пребывание в мечети с целью поклонения с соблюдением некоторых установленных правил."]]],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «Кыям рамадан», стр. 36:</b>"],["p","«Передал аль-Бейхакы, что Ибн ′Аббас (да будет доволен Аллах им и его отцом) сказал: <i>«Поистине, самыми ненавистными делами для Аллаха являются новшества, и среди таких новшеств — совершение и′тикафа в молитвенных комнатах, которые в домах». </i>"],["sep",""],["c","ГЛАВА № 4 — ОТПРАВЛЕНИЕ В МЕЧЕТЬ НА МОЛИТВУ С НАМЕРЕНИЕМ СОВЕРШАТЬ И′ТИКАФ НА ПРОТЯЖЕНИИ ВРЕМЕНИ, КОТОРОЕ ЗАЙМЕТ ЭТА МОЛИТВА<sup class=\"fn\">456</sup>"],["n",[[456,"Это распространено и в наших краях. Например, во многих мечетях висят таблички со следующей надписью: «О молящийся! Пока ты находишься в мечети, возьми намерение, что ты совершаешь и′тикаф»."]]],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в своём послании «Кыям рамадан», стр. 37:</b>"],["p","«Если человек направился в мечеть для молитвы или чего-то еще, не узаконено ему намереваться находиться в и′тикафе то время, которое он будет пребывать в мечети. Об этом ясно сказал шейх ислама в «аль-Ихтиярат»."],["sep",""],["h2","ГЛАВА № 5 — УДАЛЕНИЕ ИЗ МЕЧЕТИ ДЕТЕЙ"],["p","Некоторые делают это, считая, что возвеличивают мечеть, но это является новшеством, ибо это противоречит тому, как обстояли дела во времена пророка (да благословит его Аллах и приветствует). Этот вопрос разъяснен в книгах сунны. См. книгу шейха «Описание молитвы пророка (да благословит его Аллах и приветствует)», стр. 73. Также см. книгу «аль-Аджуиба ан-нафи′а», 114."],["sep",""],["h2","ГЛАВА № 6 — ПРЕПОДАВАНИЕ ТАК НАЗЫВАЕМЫХ ПРОПОВЕДНИЦ В МЕЧЕТИ"]],[["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, упоминая пользы, извлекаемые из хадиса под № 2680</b><sup class=\"fn\">457</sup><b> в книге «ас-Сахиха», 6/401:</b>"],["n",[[457,"В этом хадисе сказано, что пророк (да благословит его Аллах и приветствует) сказал женщинам из числа ансаров: <b><i>«Если у одной из вас умрёт трое детей, а она (проявит терпение и) будет надеяться на награду (Аллаха), то она непременно войдет в Рай». </i></b>Одна из женщин спросила: <i>«А двое, о посланник Аллаха?». </i>Он ответил: <b><i>«И двое». </i></b>"]]],["p","«Аль-Бухари привёл этот хадис в главе под названием «Выделяют ли для женщин отдельный день в мечети для приобретения знаний?»."],["p","Я скажу: например, здесь в Дамаске в последние времена распространился такой обычай, что женщины посещают мечети в определенное время, чтобы послушать, как одна из них даёт урок. Этих женщин называют проповедницами (так они думают). Это является новшеством, которого не было ни во времена пророка (да благословит его Аллах и приветствует), ни во времена праведных предшественников. Напротив, было известно, что женщин обучали праведные ученые в специально предназначенных местах, как это пришло в данном хадисе, или же в мечети отдельно от мужчин, если это возможно, чтобы они имели возможность приобретать знания и задавать вопросы."],["p","Если сегодня среди женщин будут такие, кому даровано что-то из знания и фикха, извлеченного из Корана и Сунны, то нет ничего греховного в том, чтобы они давали уроки в своём доме или в доме какой-нибудь другой женщины. Это лучше для них. А как же иначе, если пророк (да благословит его Аллах и приветствует) сказал о коллективной молитве в мечети: <b><i>«Но их дома</i></b> <i>(то есть дома женщин)</i> <b><i>лучше для них»</i></b>?! Если это касается даже молитвы, в которой женщина вынуждена будет держаться благовоспитанности и застенчивости, которых может и не быть вне молитвы, то тем более лучше для них заниматься приобретением знания в своих домах. Особенно, если учесть, что некоторые из них говорят громко, и, возможно, что одновременно будут говорить сразу несколько женщин, и тогда в мечети поднимется порицаемый гул. К сожалению, мы слышали и видели подобное лично."],["p","Затем я увидел, что это новшество перебралось и в другие города, как, например, Амман. Мы просим у Аллаха спасения от всякого новшества, внесенного в религию!»."],["sep",""],["p","<b>Также сказал наш шейх, да помилует его Аллах, комментируя хадис № 1999 в книге «Сахих ат-Таргыб уа ттархиб», 2/442: </b>"],["p","«Я привёл этот хадис также в «ас-Сахиха», № 2680. Там я также указал на то, что преподавание женщин в мечети является новшеством. Так поступают некоторые женщины, например, в Дамаске и в других местах. Истину сказал наш пророк: <b><i>«Но их дома лучше для них».</i></b>"],["sep",""],["h2","ГЛАВА № 7 — УКРАШЕНИЕ МЕЧЕТЕЙ И СВИТКОВ КОРАНА"]],[["p","<b>Шейх, да помилует его Всевышний Аллах, упомянул этот вопрос в книге «Салят ат-таравих», стр. 4-5. </b>"],["p","<b>Также в книге «ас-Сахиха» он привёл главу под названием «Нежелательность украшения мечетей и свитков Корана». А затем привёл хадис под № 1351: <i>«Если вы начнете украшать ваши мечети и ваши свитки Корана, то вас ждёт гибель!». </i></b>"],["sep",""],["h3","<b>Также наш шейх, да помилует его Всевышний Аллах, сказал в книге «ас-Самар аль-мустатаб», 1/468-470:</b>"],["p","«Первым, кто стал украшать мечети, был аль-Уалид ибн ′Абд уль-Малик ибн Маруан. Это началось в конце эпохи сподвижников. Многие обладатели знания не стали порицать это действие, так как боялись, что возникнет смута."],["p","Сказал Ибн уль-Мунеййир: <i>«Когда люди стали покрывать гипсом свои дома и украшать их, они стали делать то же самое и с мечетями, так как боялись, что в противном случае это будет считаться пренебрежительным отношением к мечетям». </i>"],["p","Сказал аш-Шаукани, 2/126: <i>«Некоторые люди объявили разрешенным украшение мечетей, опираясь на то, что предшественники не стали порицать того, кто делал это, и что это является благим новшеством, и это привлекает людей в мечети. Но на такие доводы не будет опираться тот, кому Аллах оказал содействие, особенно, если на другой стороне есть хадисы, указывающие на то, что посланник Аллаха (да благословит его Аллах и приветствует) не украшал мечети, и что это украшение мечетей является проявлением запретного высокомерия, и что это из признаков приближения Часа, как это передаётся от ′Али (да будет доволен им Аллах), и что это из действий иудеев и христиан. А ведь пророк (да благословит его Аллах и приветствует) любил противоречить им и побуждал к этому в общем и в конкретных вопросах. Нельзя опираться на то, что предшественники не порицали это, ибо украшение мечетей — это такое новшество, которое ввели несправедливые обладатели власти, не спрашивая разрешения у обладателей знания и достоинства. Они ввели столько новшеств, сколько не сосчитать, но никто их не порицал. Ученые молчали из страха, а не из-за того, что были довольны ими. Но затем против их лживых дел встала целая группа ученых, а они прямо перед ними объявили о желании казнить их. </i>"],["p","<i>Также ложной является аргументация тем, что это новшество является благим. Мы разъяснили тебе, почему это заявление является ложным, когда разъясняли хадис: </i><b><i>«Если кто-либо совершит дело, относительно которого не было нашего приказа, то оно будет отвергнуто». </i></b><i>Это разъяснение было в главе о совершении молитвы в шелковой одежде и в той одежде, которая несправедливо присвоена. Также ложным является заявление о том, что это привлекает людей в мечети, ибо оно привлекает к мечетям только тех, чья главная цель — это созерцание этих росписей и украшений. Те же люди, которые стремятся в мечети для поклонения Аллаху, (а поклонение будет истинным только при наличии смирения, а иначе оно будет, словно тело без духа), только лишь отвлекаются из-за этих украшений. Именно поэтому пророк (да благословит его Аллах и приветствует) отказался от одежды, которую отправил к нему Абу Джахм. Также мы уже приводили хадис о том, что он сорвал занавеси, на которых были росписи. Также далее будет приведена глава об удалении того, что отвлекает молящегося спереди». </i>"]],[["p","Но заявления о том, что предшественники не порицали тех, кто украшал мечети, в целом является ложным. На это указывает то, что передал Са′ид ибн Мансур от Исма′иля ибн ′Абд ур-Рахмана ибн Зувейба, который рассказывал: <i>«Однажды я с Ибн ′Умаром посетил мечеть в Джухфе. Он увидел её балконы, затем удалился в другое место и совершил молитву, а затем сказал владельцу мечети: «Я видел в твоей мечети эти (балконы), похожие на жертвенники, стоявшие во времена джахилии. Прикажи сломать их!». </i>"],["p","Это предание приведено в книге «Иктида ас-сырат аль-мустакым фи мухаляфати асхаб аль-джахим», шейха ислама Ибн Теймии, стр. 63. Его цепочка передатчиков являются достоверной. Все передатчики являются крепкими и надежными и от всех них передают авторы шести сборников, за исключением этого Исма′иля, но он так же является крепким, как об этом сказано в «ат-Такриб»."],["p","В книге «аль-Мудаввана» Ибн уль-Касима, 1/109, сказано: <i>«Я слышал, как Малик упомянул мечеть Медины и то, как её украсили, и сказал: \"Люди (то есть ученые) не хотели этого, когда это сделали, и это отвлекает людей во время молитвы. Они смотрят на эти узоры и отвлекаются\"».</i>"],["p","Именно поэтому многие ученые назвали нежелательной молитву в разукрашенной мечети»."],["sep",""],["h2","ГЛАВА № 8 — МИХРАБЫ В МЕЧЕТЯХ"],["p","<b>Наш шейх, да помилует его Всевышний Аллах, разбирал вопрос, связанный с михрабами, и их узаконенностью. Шейх, да помилует его Всевышний Аллах, в книге «ад-Да′ифа» привёл хадис под № 448</b><sup class=\"fn\">458</sup><b>, назвал его слабым, а затем сказал, 1/641-643:</b>"],["n",[[458,"В этом хадисе сказано: <b><i>«Эта община не перестанет пребывать во благе, пока не станет делать в своих мечетях алтари, подобные алтарям христиан». </i></b>"]]],["p","«<b>Польза</b>: алтари (мазабих) — это михрабы, как об этом сказано в «Лисан аль-′араб» и других книгах. Также это пришло в хадисе Ибн ′Амра, где пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Остерегайтесь этих алтарей (мазабих)». </i></b>То есть михрабов. Передал аль-Бейхакы, 2/439, и другие с достоверной цепочкой передатчиков. Сказал ас-Суюты в своём послании<sup class=\"fn\">459</sup>, стр. 21: <i>«Хадис достоверный». </i>"],["n",[[459,"Имеется в виду книга «Оповещение смышленых о том, что михрабы являются новшеством»."]]],["p","Он привёл этот хадис в качестве довода на запретность установления михрабов в мечетях, но этот вопрос нуждается в рассмотрении. Я разъяснил его в книге «ас-Самар аль-мустатаб фи фикх ас-Сунна уаль Китаб». Суть в том, что в этих хадисах имеется в виду возвышенное место, где (имам) садится перед людьми, как об этом сказал аль-Мунауи в «аль-Файд»."],["p","Да, ас-Суюты сказал в вышеупомянутом послании, что михрабы в мечети являются новшеством. За ним последовал шейх ′Али аль-Кари в «Миркат аль-мафатих», 1/473, и другие. Этот хадис ясно запрещает это, но в его цепочке передачи есть разрыв, а мы не считаем для себя разрешенным аргументировать тем, что не передано от пророка (да благословит его Аллах и приветствует) достоверно."]],[["p","Аль-Баззар, 1/210/416, передал, что Ибн Мас′уд не любил совершать молитву в михрабе. Он сказал: <i>«Эти михрабы предназначены для церквей. Не уподобляйтесь же людям Писания!». </i>То есть ему не нравилось совершение молитвы в этих сводах."],["p","Сказал аль-Хейсами, 2/51: <i>«Передатчики являются крепкими». </i>"],["p","Я скажу: его слова нуждаются в рассмотрении. Аль-Баззар указал на то, что его передал только Абу Хамза от Ибрахима. Абу Хамза — это Маймун аль-Кассаб. Он является слабым по единогласному мнению, и никто не называл его крепким передатчиком. То есть именно он является основной причиной слабости этого хадиса. Однако этот хадис усиливается тем, что передал Ибн Аби Шейба с достоверной цепочкой от Ибрахима, который сказал, что ′Абдуллах (ибн Мас′уд) сказал: <i>«Остерегайтесь этих михрабов». </i>И поэтому Ибрахим не становился в них."],["p","Я скажу: это является достоверным от Ибн Мас′уда, а Ибрахим — это Ибн Язид ан-Наха′и. На самом деле, Ибрахим не слышал хадисы от Ибн Мас′уда, но целая группа имамов всё равно назвала эти передачи достоверными. Аль-Бейхакы сказал, что именно то, что передаёт Ибрахим от Ибн Мас′уда является достоверным, несмотря на разрыв в цепочке."],["p","Я скажу: эти слова являются верными, ведь аль-А′маш передал: <i>«Однажды я сказал Ибрахиму: \"По какой цепочке ты передаешь от Ибн Мас′уда?\". Он ответил: «Если я говорю: \"Сказал ′Абдуллах\", то, значит, многие передатчики передали мне эти слова от Ибн Мас′уда\"».</i>"],["p","Эти слова передали аль-Хафиз (Ибн Хаджар) в «ат-Тахзиб», ат-Тахауи, 1/133; Ибн Са′д в «ат-Табакат», 6/272; Абу Зур′а в «Тарих Димашк», 2/121, с достоверной цепочкой передатчиков."],["p","Я скажу: и в разбираемом нами предании Ибрахим сказал: «Сказал ′Абдуллах». Значит, он перенял эти слова от многих учеников Ибн Мас′уда. Душа спокойна к их хадисам, ибо их много, даже если их имена точно нам неизвестны. Дело в том, что большинство последователей сподвижников были правдивыми людьми, а, особенно, ученики Ибн Мас′уда (да будет доволен им Аллах)."],["p","Затем Ибн Аби Шейба передал от Салима ибн Аби-ль Джа′да, что он сказал: <i>«Не делайте алтари в мечетях!». </i>Цепочка передатчиков достоверная."],["p","Затем он передал с достоверной цепочкой, что Муса ибн ′Убейда сказал: <i>«Я видел мечеть Абу Зарра, но не видел в нём этого свода». </i>"],["p","В общем, он передал много преданий от предшественников о том, что они не любили эти михрабы в мечетях. Но достаточно даже того, что мы упомянули здесь."],["p","Шейх аль-Каусари в предисловии к вышеупомянутому посланию ас-Суюты, стр. 17, сказал, что михрабы присутствовали в мечети пророка (да благословит его Аллах и приветствует). Но эти слова противоречат этим преданиям, и если человек прочитает эти предания, он точно скажет о том, что михрабы являются новшеством. И, конечно же, об этом сказала целая группа ученых, как мы уже приводили. Аль-Каусари опирался на хадис, который не является достоверным, и мы должны разобрать этот вопрос подробнее, чтобы опровергнуть эти подтасовки со стороны аль-Каусари."]],[["p","В хадисе пришло, что Уаиль ибн Худжр рассказывал: <i>«Я присутствовал, когда посланник Аллаха (да благословит его Аллах и приветствует) пришёл в мечеть, вошёл в михраб, затем поднял руки, произнеся такбир, а затем положил правую руку на левую над грудью». </i>"],["h3","<b>Затем наш шейх назвал данный хадис слабым и сказал, 1/644-647:</b>"],["p","«Также к посланию ас-Суюты сделал предисловие другой человек — шейх ′Абдуллах Мухаммад ас-Сыддик аль-Гумари, и он уже был справедлив в словах об этом хадисе, хоть и он согласился с аль-Каусари в том, что михрабы являются хорошей вещью. Но он назвал этот хадис слабым. Он на стр. 20 словно опровергает аль-Каусари и говорит:"],["p","<i>«Истина заключается в том, что хадис является слабым из-за неизвестности Умм ′Абд уль-Джаббар. А также из-за того, что Мухаммад ибн Худжр ибн ′Абд уль-Джаббар передавал отвергаемые хадисы, как об этом сказал аз-Захаби. Но даже если представить, что этот хадис достоверный, то мы должны понимать под словом «михрабы» места для молитвы, ибо точно известно, что тогда в мечети пророка не было михрабов (в современном понимании этого слова), и об этом как раз сказал автор (ас-Суюты), а также аль-Хафиз и ас-Сеййид ас-Самхуди». </i>"],["p","Я скажу: и если хадис достоверен, то именно такое толкование и будет правильным, ибо, передавая этот хадис, аль-Баззар добавил: <i>«То есть место, где (сейчас) михраб». </i>То есть он прямо сказал о том, что михраба не было во времена пророка (да благословит его Аллах и приветствует). Именно поэтому передатчик и сказал: <i>«То есть место, где (сейчас) михраб».</i>"],["p","Из этого беспристрастный читатель поймет ошибочность того, что аль-Каусари схватился за этот хадис. Он ошибся и со стороны цепочки передатчиков, и со стороны смысла хадиса. И ему не приносит пользы даже то, что передал ат-Табарани<sup class=\"fn\">460</sup> со слов Сахля ибн Са′да (да будет доволен им Аллах). В его хадисе сказано: <i>«…и когда ему построили михраб, он подошёл к нему…». </i>"],["n",[[460,"В книге «аль-Му′джам аль-кабир», 6/155/5726. Шейх аль-Альбани разобрал цепочку этого хадиса и разъяснил, что упоминание михраба в этом хадисе является отвергаемым."]]],["p","Эти слова в хадисе <i>«…и когда ему построили михраб…» </i>являются отвергаемыми. Их передал только ′Абд уль-Мухаймин, однако многие ученые назвали его слабым, как об этом сказал аль-Каусари. Но, на самом деле, его положение еще хуже. Аль-Бухари сказал о нём: <i>«Его хадисы являются отвергаемыми». </i>Ан-Насаи сказал: <i>«Он не является крепким». </i>Иначе говоря, он является очень слабым. Его хадисы не берутся в качестве поддержки, как это известно из науки хадисоведения. И это даже если мы согласимся с тем, что эта версия хадиса соответствует хадису Уаиля. Но, на самом деле, эти хадисы являются абсолютно разными, как мы уже разъяснили."]],[["p","Что касается того, что аль-Каусари и другие называли михрабы хорошим явлением, опираясь на то, что в них есть очевидная польза, а именно указание на направление Каабы, то эта аргументация является слабой с многих сторон."],["p","<b>Во-первых</b>, в большинстве мечетей есть минбары, и они, без сомнений, выполняют эту функцию, а, значит, нет нужды в михрабах. Если бы люди, разногласящие в этом вопросе, были справедливы, они бы согласились с этим и не стали бы выдумывать эти оправдания."],["p","<b>Во-вторых</b>, если что-то узаконено по причине нужды и пользы, то следует остановиться там, где требует эта польза, не переходя за эти рамки. Если целью михрабов в мечетях является указание на направление молитвы, то для этого достаточно совсем маленького углубления, но мы видим, что в большинстве мечетей михрабы являются огромными и широкими, и имам полностью помещается в них. К тому же они стали местом украшений и росписей, которые отвлекают молящихся и лишают их смирения в молитве, и привлекают к себе их мысли. А это, без сомнений, запрещено."],["p","<b>В-третьих</b>, если установлено, что эти михрабы являются обычаем христиан в их церквях, то следует полностью отказаться от михрабов и заменить их чем-то другим. Например, можно установить столб возле места имама, ибо этому есть основа в Сунне. Передал ат-Табарани в «аль-Кабир», 1/89/2, и в «аль-Аусат», 2/284/9296, что Джабир ибн Усама аль-Джухани рассказывал:"],["p","<i>«Однажды я встретил пророка (да благословит его Аллах и приветствует) с его сподвижниками на рынке и спросил сподвижников посланника Аллаха (да благословит его Аллах и приветствует): \"Куда он направляется?!\". Они сказали: \"Он планирует для твоего народа мечеть\". Когда я вернулся, я спросил у людей: \"Что с вами?!\". Они сказали: \"Посланник Аллаха (да благословит его Аллах и приветствует) расчертил для нас мечеть и установил в направлении Каабы кусок дерева». </i>"],["p","Я скажу: эта цепочка передатчиков является хорошей или близкой к хорошей. Все передатчики хадиса являются крепкими и известными, но среди ученых есть разногласия относительно ат-Тейми."],["p","Суть в том, что михрабы в мечети являются новшеством. Мы никак не может назвать это чем-то полезным и разрешенным, ибо есть то из шариата посланника Аллаха (да благословит его Аллах и приветствует), что может легко заменить эти михрабы. К тому же это<sup class=\"fn\">461</sup> дальше от разукрашивания мечети»."],["n",[[461,"То есть столб возле места стояния имама."]]],["sep",""],["h2","ГЛАВА № 9 — МИНБАР, У КОТОРОГО БОЛЬШЕ ТРЁХ СТУПЕНЕК"],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в книге «Описание молитвы пророка (да благословит его Аллах и приветствует)», стр. 81:</b>"]],[["p","«В соответствии с Сунной минбар должен быть из трёх ступенек (не более этого). Добавление большего количества ступенек — это новшество, которое внесли омеяды. Очень часто минбары даже разрывают первых ряд молящихся. Некоторые люди пытаются избежать этого и устанавливают минбар в западном углу мечети или в михрабе, но это — еще одно новшество. То же самое касается того, когда минбар делают на южной стене в виде балкона, а имам поднимается на этот балкон по лестнице, прилегающей к стене. Лучший путь — это путь Мухаммада (да благословит его Аллах и приветствует). Обратись к книге «аль-Фатх», 2/331»."],["sep",""],["p","<b>Также сказал наш шейх, да помилует его Всевышний Аллах, в «ас-Самар аль-мустатаб», 1/413-414, давая совет тем, кто желает построить мечеть, чтобы они насколько это возможно, сделали в мечети меньше столбов:</b>"],["p","«Именно поэтому я говорю, что следует тому, кто собирается построить мечеть, велеть инженерам составить чертёж так, чтобы в мечети было как можно меньше столбов, дабы уменьшить тот вред, который следует за присутствием столбов в мечети, а именно — прерывание рядов и уменьшение пространства для молящихся. Например, сегодня можно построить мечеть вообще без столбов при помощи бетона, если, например, мечеть не является слишком огромной. В Дамаске построили сразу несколько мечетей такой конструкции. Например, мечеть «Ляля Баша» на Багдадской улице, также соборная мечеть аль-Мурабит в район аль-Мухаджирин и т. д<sup class=\"fn\">462</sup>. Ряды в этих двух мечетях неразрывны, за исключением передних рядов, которые, к сожалению, разорваны, и это по причине этого новшества, которое, как кажется, охватило все мечети. Я имею в виду высокие и длинные минбары, у которых много ступенек. Это является новшеством, противоречащим пути пророка (да благословит его Аллах и приветствует). Его минбар состоял из трёх ступенек. Я уже не говорю о том, что эти минбары разукрашены и расписаны, и на них бессмысленно потрачены деньги. Но помимо этого это новшество так же, как и столбы, разрывает ряд молящихся. Более того оно приносит еще больше вреда, ибо из-за длины этих минбаров они разрывают сразу много рядов. Ученые обязаны разъяснять это и во время своих уроков и проповедей призывать к устранению этих минбаров и возвращению к тому, каким был минбар пророка (да благословит его Аллах и приветствует). И те, кто обладает властью, должны вернуться к тем минбарам и избавить молящихся от этого вреда."],["n",[[462,"В примечаниях к этой книге сказано следующее: «Также, например, мечеть Му′ауии ибн Аби Суфьяна в районе аль-Мушейрифа (Иордания). Эта мечеть была возведена по советам нашего шейха аль-Альбани, да помилует его Аллах. Сейчас ею руководит «Центр имама аль-Альбани по научным исследованиям». Также, например, мечеть аль-Бары ибн Малика в том районе, в котором я живу. А ведь она является большой и просторной, и при этом в ней нет ни одного столба. Также, например, мечеть «ат-Такуа» на горе ан-Наср. Она также была возведена по советам шейха»."]]]],[["p","Также у этих минбаров есть еще одно дурное последствие, которого нет у столбов. Они иногда приводят к нарушению молитвы, и мы много раз видели это. Часто бывает так, что имам забывает прочитать первый ташаххуд, произносит такбир, встаёт на третий ракаат и за ним следуют молящиеся позади. Но те молящиеся, которые за минбаром с правой стороны, не видят, что имам ошибся, и думают, что он правильно произнёс такбир, и остаются сидеть для ташаххуда, хотя имам уже стоит. И вот, когда имам произносит такбир и совершает уже поясной поклон, эти молящиеся только встают. Они даже не знают, что противоречат имаму и не следуют за ним, пока имам не поднимет голову с поясного поклона и не скажет: «Аллах слышит того, кто Его восхваляет». И здесь, как говорят, и смех, и слезы. Ты видишь, что кто-то из них вообще прерывает молитву и начинает её заново, а кто-то пытается догнать имама и продолжить молиться с ним, встает с ташаххуда, затем стоит секунду, а затем совершает поясной поклон, затем выпрямляется и догоняет имама уже в земном поклоне или даже позже."],["p","А иногда случается нечто еще более удивительное. Иногда бывает так, что кто-то из молящихся исправляет имама, когда тот хочет встать на третий ракаат без чтения ташаххуда по ошибке. Кто-то из молящихся говорит: «Субхана Ллах». Те люди, которые молятся за минбаром, слышат это и понимают, что имам ошибся, но при этом они не знают, что дальше делает имам: либо он вернулся на ташаххуд, и тогда они должны остаться сидеть, либо же он начал третий ракаат, и тогда ему уже нельзя возвращаться на ташаххуд, а, значит, он остаётся стоять, и они должны стоять с ним. Поэтому ты видишь, что они попадают в трудное положение: некоторые из них остаются сидеть, другие — стоят, третьи — сначала садятся, потом встают, четвертые — наоборот сначала встают, а потом садятся, думая, что имам сделал именно так. Всё это происходит из-за противоречия пути пророка (да благословит его Аллах и приветствует) в вопросах минбара. Надеюсь, на это обратят внимание те, кто управляет мечетями, и исправят эту ситуацию."],["p","<b>«Воистину, в этом заключено напоминание для тех, у кого есть сердце, кто прислушивается и присутствует при этом»</b><sup class=\"fn\">463</sup>."],["n",[[463,"Сура «Каф», аят 37."]]],["p","Именно поэтому некоторые ученые из числа предшественников считали, что прерванный из-за минбара ряд не считается первым рядом. Первым рядом считается непрерывный ряд перед минбаром."],["p","Сказал аль-Газали в «аль-Ихья», 1/164-165:"],["p","<i>«Когда человек стремится попасть в первый ряд, он не должен забывать о трёх вещах». </i>"],["p","Он упомянул первые два пункта, а затем сказал:"]],[["p","<i>«В-третьих, иногда минбар разрывает ряды, и тогда первым рядом считается тот ряд, который непрерывен перед минбаром. А те молящиеся, которые молятся по бокам от минбара; их ряд считается прерванным. Ас-Саури говорил: «Первый ряд — это ряд, который перед минбаром». Это мнение является хорошим, ибо именно этот ряд будет непрерывным, а также из-за того, что сидящий в этом ряду сидит лицом к проповеднику и слышит его. Но и мнение о том, что первый ряд — это тот ряд, который ближе всего к Каабе, не является далеким от истины. Это мнение не принимает во внимание тот предыдущий смысл». </i>"],["p","Это последнее утвердил также ан-Науауи в «аль-Маджму′», 4/301, сказав:"],["p","<i>«И знай, что первый ряд — это тот ряд, который сразу за имамом вне зависимости от того, разрывает ли его минбар, столбы или что-то подобное или не разрывает». </i>"],["p","Как бы ни было, молитва за минбаром является нежелательной, ибо это подвергает молитву нарушению. И человеку либо следует молиться с другой стороны минбара, откуда он будет видеть движения имама, или же молиться в другом ряду. Именно так поступаем мы, если пожелает Всевышний Аллах. Мы не совершаем молитву между столбами: мы либо идём немного назад, либо немного вперед. Так поступал Анас ибн Малик. И мы не видим разницы между этим и между молитвой за минбаром, ибо причина одна и та же. И к тому же молитва за минбаром в отличие от молитвы между столбами может повлечь к нарушению молитвы, как мы уже сказали. А Всевышний Аллах знает лучше!»."],["sep",""],["h2","ГЛАВА № 10 — УСТАНОВЛЕНИЕ МИНБАРА У ЗАПАДНОЙ СТЕНЫ МЕЧЕТИ ИЛИ ЖЕ УСТАНОВЛЕНИЕ ЕГО В ВИДЕ БАЛКОНА НА ЮЖНОЙ СТЕНЕ"],["p","<b>Этот вопрос был упомянут при разъяснении предыдущего вопроса. </b>"],["sep",""],["c","ГЛАВА № 11 — ВЫДЕЛЕНИЕ В МЕЧЕТИ СПЕЦИАЛЬНЫХ КОМНАТ, ПРЕДНАЗНАЧЕННЫХ ДЛЯ СУФИЕВ, ГДЕ ОНИ БУДУТ ПРОВОДИТЬ СВОИ ПОМИНАНИЯ, ВИРДЫ И ПРАЗДНИКИ"],["h3","<b>Сказал аль-Касими, да помилует его Всевышний Аллах, в «Ислях аль-масаджид», стр. 177: </b>"],["p","«Именно поэтому является прекрасным решением то, что они собираются в отдельных углах мечети или комнатах, которые предназначены именно для них и их братьев, и тех, кто желает присутствовать на их праздниках и собраниях»."],["p","<b>Сказал наш шейх аль-Альбани, да помилует его Всевышний Аллах, в примечаниях к книге «Ислях аль-масаджид», стр. 177:</b>"],["p","«Напротив, это было внесено в религию, а <b><i>«всё, что было внесено в религию, является новшеством, и каждое новшество — заблуждение, а каждое заблуждение — в Огне», </i></b>как сказал пророк (да благословит его Аллах и приветствует)»."],["sep",""],["h2","ГЛАВА № 12 — МИНАРЕТЫ ДЛЯ АЗАНОВ В МЕЧЕТЯХ"],["p","<b>Наш шейх передал от аш-Шатыби в его книге «аль-И′тисам» и от других ученых, что азан во времена пророка (да благословит его Аллах и приветствует) в пятничный день произносили с минарета. То же самое он передал от Ибн уль-Хаджжа в его книге «аль-Мадхаль». Но шейх, да помилует его Всевышний Аллах, не согласился с этим мнением. Он сказал в «аль-Аджуиба ан-нафи′а», стр. 33-35:</b>"]],[["p","«Были ли минареты во времена пророка (да благословит его Аллах и приветствует)?!"],["p","Я скажу: я не нашел ничего, что прямо бы указывало на то, что азан во времена пророка (да благословит его Аллах и приветствует) произносили на минаретах. Я нашел лишь хадис, в котором говорится, что азан произносили у дверей мечети. Кажется, имеется в виду, что его произносили на крыше, которая над дверью. И это поддерживается тем, что известно, что у Биляля, который произносил азан в пятничный день, было что-то вроде лестницы, чтобы он мог подниматься и произносить азан."],["p","В «Сахихе» аль-Бухари, 4/100, пришло, что ′Аиша, да будет доволен ею Аллах, сказала: <i>«Биляль произносил азан ночью, и посланник Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Ешьте и пейте, пока не произнесет азан Ибн Умм Мактум, ибо он произносит азан лишь тогда, когда появляется заря\"</i></b><i>». </i>"],["p","Аль-Касим (передатчик этого хадиса) сказал: <i>«А между их азанами проходило лишь такое время, за которое один успевал спуститься, а другой подняться». </i>"],["h3","<b>Затем наш шейх продолжил: </b>"],["p","«Из того, что я вывел для себя на эту тему, следующее: не установлено достоверно, что во времена пророка (да благословит его Аллах и приветствует) в мечетях были известны эти минареты. Но точно можно сказать, что тогда азан произносили на возвышенном месте, куда поднимался муаззин, как это было приведено. Возможно предположить, что муаззин поднимался на крышу мечети, а, возможно, предположить, что он поднимался на что-то над самой крышей, как это пришло в хадисе Умм Зейд. Вне зависимости от того, как именно обстояло дело, мы точно можем сказать, что те минареты, которые известны сейчас, не имеют к Сунне никакого отношения. Но также следует сказать, что смысл этих минаретов — это донесение азана до людей, а эта цель узаконена, вне всякого сомнения. Если невозможно донести азан до людей как-то иначе, то эти минареты будут узаконенными, ибо установлено в науке об основах фикха, что если без чего-то нельзя выполнить обязанность, то эта вещь также является обязательной по мере нужды в ней."],["p","Однако я считаю, что сейчас мы имеем микрофоны и громкоговорители, и поэтому нет нужды в этих минаретах для донесения азана. Особенно, если учесть, что на них тратятся огромные деньги. То есть их возведение является новшеством, и в них нет никакой нужды, и это приводит к расточительству и бессмысленной трате денег. Также на то, что они сегодня лишены пользы, указывает и то, что муаззины никогда не поднимаются на эти минареты, а дают азан в микрофон»."],["sep",""],["h2","ГЛАВА № 13 — БОЛЬШОЕ КОЛИЧЕСТВО МЕЧЕТЕЙ В ОДНОМ МЕСТЕ"]],[["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в своей ценной книге «ас-Самар аль-мустатаб фи фикх ас-Сунна уаль Китаб», 1/450-451:</b>"],["p","«Ибн Хазм привёл хадис Ибн ′Аббаса, в котором сказано: <i>«…и мне не было приказано покрывать гипсом мечети…»</i><sup class=\"fn\">464</sup>. Затем он сказал, 4/44:"],["n",[[464,"Шейх аль-Альбани, да помилует его Всевышний Аллах, назвал этот хадис достоверным в соответствии с условиями Муслима."]]],["p","<i>«Пророк (да благословит его Аллах и приветствует) не приказывал строить мечети во всех местах, но он приказывал строить мечети в кварталах. То, что запретил пророк (да благословит его Аллах и приветствует), отличается от того, что он приказал. И если дело обстоит так, то мечети нужно строить так, как он разъяснил своими повелениями и действиями. То есть нужно строить мечети в кварталах, как и сказал пророк (да благословит его Аллах и приветствует)». </i>"],["p","Также он сказал:"],["p","<i>«В Медине пророк (да благословит его Аллах и приветствует) строил по одной мечети для каждого квартала. То есть одна мечеть должна охватывать такую территорию, с которой людям не сложно приходить на все пять молитв. Если же мечетей больше или меньше, то пророк (да благословит его Аллах и приветствует) не поступал так, и это является ложным и порицаемым, а порицаемое нужно изменять». </i>"],["p","Также он сказал:"],["p","<i>«Ибн Мас′уд разрушил мечеть, которую построил ′Амр ибн ′Утба за пределами Куфы, и вернул его в соборную мечеть»</i><sup class=\"fn\">465</sup>."],["n",[[465,"Сказал шейх ислама Ибн Теймия (да помилует его Аллах) в «Тафсир сурат аль-Ихляс», стр. 172-173: <i>«Именно поэтому предшественники считали, что старые мечети лучше новых, ибо старые мечети дальше от того, чтобы им могли построить для вреда, чем новые мечети, где присутствует такая опасность. Если мечеть является старой, это является похвальным качеством. Именно поэтому Аллах сказал: </i><b>«…а место их заклания — у древнего Дома». </b><i>(Сура «аль-Хаджж», аят 33). А также: </i><b>«Воистину, первым домом, который воздвигнут для людей, является тот, что находится в Бекке (Мекке)». </b><i>(Сура «Али ′Имран», аят 96). Если мечеть является старой, это также указывает на то, что в ней много поклонялись Аллаху, а это влечёт увеличение её достоинства». </i>"]]],["sep",""],["h2","ГЛАВА № 14 — БОЛЬШОЕ КОЛИЧЕСТВО СВЕТИЛЬНИКОВ В МЕЧЕТЯХ ПО ПРИЧИНЕ НЕКОТОРЫХ ЗНАМЕНАТЕЛЬНЫХ ДАТ"],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ас-Самар аль-мустатаб фи фикх ас-Сунна уаль Китаб», 2/597-600:</b>"],["p","«Некоторые люди разжигают множество светильников в различных мечетях по причине некоторых событий или праздников (например, первая пятница месяца раджаб, срединная ночь месяца ша′бан, месяц рамадан, праздник разговения и жертвоприношения), но это является запретным деянием, особенно, если это делается в праздник разговения и жертвоприношения. В эти дни светильники остаются включенными до самого раннего утра."]],[["p","Сказал Ибн уль-Хаджж, да помилует его Аллах, в «аль-Мадхаль», говоря о новшествах, связанных со срединной ночью ша′бана, 1/308:"],["p","<i>«Разве ты не видишь, что они сделали, а именно увеличили количество светильников до такой степени, что не оставили в соборных мечетях ламп, кроме как разожгли их?! Также они повесили веревки на столбах и балконах, а затем повесили на них лампы и разожгли их. Мы уже говорили о том, почему ученые (да помилует их Аллах) считали нежелательным обтираться о свитки Корана, минбар и стены… Именно это стало причиной появления поклонения идолам. Когда люди разжигают дополнительные светильники (на праздники), в этом есть внешнее уподобление тем, кто поклоняется огню, даже если люди и не собирались им уподобляться. Ведь огнепоклонники разжигают огонь, а когда он разгорается до предела, они собираются вокруг него с намерением поклонения. Пророк (да благословит его Аллах и приветствует) побудил мусульман отказаться от уподобления действиям сторонников ложных религий, даже если это касается одежд, которые они носят. </i>"],["p","<i>К тому же в эти дни происходит собрание множества мужчин, женщин и маленьких детей, которые, как правило, загрязняют мечеть, много шумят, занимаются бесполезными делами. Мы уже разъясняли, сколько в этом дурных последствий. Но именно в двадцать седьмую ночь раджаба этого происходит больше и еще в худшем виде, потому что люди в этот день разжигают эти светильники. Посмотри же, да помилует Аллах нас и вас, на эти новшества, как они влекут за собой еще другие новшества, а в результате люди приходят к совершению запретных поступков». </i>"],["p","В книге «аль-Ба′ис ′аля инкар аль-бида′ уаль хауадис», стр. 22-23, передано, что Абу Бакр ат-Тартуши, да помилует его Аллах, сказал:"],["p","<i>«Некоторые сторонники новшеств вышли за рамки шариата и внесли новшества, и последовали этим по пути огнепоклонников. Они превратили свою религию в забаву и игру. Я имею в виду разжигание светильников в срединную ночь ша′бана. Относительно этого нет ничего достоверного от посланника Аллаха (да благословит его Аллах и приветствует). Ни один передатчик не передавал, что в эту ночь нужно совершать какую-то особую молитву или разжигать лампы. Но внесли это новшество некоторые люди, которые играют с шариатом Мухаммада (да благословит его Аллах и приветствует) и стремятся к религии огнепоклонников, потому что огонь — их объект поклонения. Первый раз это появилось во времена династии бармакидов, которые внесли в религию ислам то, чем они обманули простых людей. Они начали разжигать лампы в месяце ша′бан, как будто бы это действие относится к обычаям веры, хотя их целью было поклонение огню и распространение своей религии, которая относится к числу самых убыточных. И получилось так, что мусульмане совершали молитву, кланялись и падали ниц, но делали это в направление огней, которые те разожгли, и это продолжалось множество лет, и за Багдадом в этом последовали и другие области. Я уже не говорю о том, что в эту ночь происходит смешение мужчин и женщин. Правитель обязан запретить им это, а ученый обязан их предостерегать. Почёт месяца ша′бан в том, что посланник Аллаха (да благословит его Аллах и приветствует) соблюдал в нём пост, (а не в этих огнях). В достоверном хадисе передано, что он соблюдал пост на протяжении всего этого месяца или на протяжении большей его части». </i>"]],[["p","Затем Абу Шама сказал на стр. 25:"],["p","<i>«Всё это зло появилось со стороны тех, кто изображает из себя праведников и вводит людей в заблуждение. А что уже сказать о том, что совершают нечестивцы, заполняя эту ночь различными явными и скрытыми грехами?! И всё это по причине чрезмерного количества ламп, разжигая которые, люди думают, что совершают поклонение. Но, на самом деле, это является помощью в ослушании Всевышнего Аллаха и открытым выставлением порицаемого напоказ, и усилением обрядов сторонников новшеств. В шариате не пришло ничего о том, что желательно разжигать чрезмерное количество ламп в каком-либо месте. Также подобно этому то, что совершают паломники из числа простого народа, которые разжигают лампы в день ′Арафата и в ночь перед жертвоприношением на Заповедной территории. Необходимо порицать это и говорить о том, что это является новшеством, порицаемым явлением и противоречием пречистому шариату». </i>"],["sep",""],["h2","ГЛАВА № 15 — ПРОДАЖА ОДЕЖДЫ ВОЗЛЕ МАКАМА (МЕСТО СТОЯНИЯ ИБРАХИМА). ПРОДАЖА КНИГ И ДРУГИХ ТОВАРОВ В ЗАПОВЕДНОЙ МЕЧЕТИ"],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ас-Самар аль-мустатаб фи фикх ас-Сунна уаль Китаб», 2/694-695:</b>"],["p","«Сказал ас-Сан′ани в своём толковании:"],["p","<i>«В этом указание на то, что запрещено покупать и продавать в мечети, а если кто-то видит подобное в мечети, он обязан сказать покупателю и продавцу: «Пусть Аллах не сделает прибыльной твою торговлю!». Он должен сказать это вслух, чтобы тот, кто совершает это, остановился. А причина в том, о чем мы уже говорили ранее: мечети не были построены для этих целей». </i>"],["p","Сказал шейх ′Али аль-Кари в «аль-Миркат», 1/467:"],["p","<i>«К числу отвратительных новшеств относится продажа одежды для паломников за макамом (местом стояния Ибрахима возле Каабы), а также продажа книг и т. п. в Заповедной мечети. А еще хуже, когда люди кладут там ящики, бурдюки и различный хлам (для продажи). Особенно это заметно в дни хаджа, когда в этих местах много людей. А Аллах является покровителем Своей религии! И нет силы и мощи, кроме как с Ним!». </i>"],["h2","РАЗДЕЛ ЧЕТЫРНАДЦАТЫЙ — НОВШЕСТВА, СВЯЗАННЫЕ С ПЯТНИЧНЫМ ДНЁМ"],["h2","ГЛАВА № 1 — ОТКАЗ ОТ ВЫХОДА В ПУТЬ В ПЯТНИЦУ<sup class=\"fn\">466</sup>"],["n",[[466,"Передал Ибн Аби Шейба в «Мусаннафе», 1/205/1, со слов Салиха ибн Кейсана, что Абу ′Убейда однажды вышел в путь в пятницу и не стал дожидаться пятничной молитвы. Цепочка передатчиков хорошая. Также передали Ибн Аби Шейба, имам Мухаммад ибн уль-Хасан в «ас-Сейр аль-кабир», 1/50, и аль-Бейхакы, 3/187, что ′Умар (да будет доволен им Аллах) сказал: <i>«Пятничный день не должен препятствовать отправлению в путь». </i>Цепочка передатчиков достоверная. Затем Ибн Аби Шейба передал то же самое от целой группы предшественников. Что же касается хадиса: <b><i>«Если кто-либо выйдет в путь после утренней молитвы в пятницу, против него будут обращаться с мольбами два ангела», </i></b>то он является слабым. Шейх аль-Альбани указал на это в книге «аль-Ахадис ад-да′ифа», 218, 219."]]]]];
